export default "import { EmbeddedScene, SceneAppPage, SceneAppPageState, SceneCSSGridLayout, VizPanel } from '@grafana/scenes';\nimport { getEmbeddedSceneDefaults, getQueryRunnerWithRandomWalkQuery } from './utils';\n\nexport function getSeriesLimitTest(defaults: SceneAppPageState) {\n  return new SceneAppPage({\n    ...defaults,\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        body: new SceneCSSGridLayout({\n          children: [\n            new VizPanel({\n              title: 'Many series',\n              pluginId: 'timeseries',\n              seriesLimit: 20,\n              $data: getQueryRunnerWithRandomWalkQuery({ seriesCount: 50 }),\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\n";